import {Config} from 'alinea'

export const main = Config.workspace('My site', {
  source: 'content',
  mediaDir: 'public/media',
  roots: {
    pages: Config.root('Pages'),
    media: Config.media()
  }
})

import {Config, Field} from 'alinea'

export const Photo = Config.file('Photo', {
  accept: 'image/*',
  fields: {
    alt: Field.localised(Field.text('Alt text')),
    credit: Field.text('Credit')
  }
})

export const Logo = Config.file('Logo', {accept: 'image/*'})
export const Download = Config.file('Download', {accept: '.pdf,.docx'})

export const Folder = Config.type('Folder', {
  contains: ['Folder', 'Photo', 'Logo', 'Download'],
  fields: {}
})

Config.root('Library', {
  contains: ['Folder', 'Photo', 'Download'],
  i18n: {locales: ['en', 'nl'], translate: 'fields'}
})

import {Config, Field} from 'alinea'
import {createCMS} from 'alinea/next'

export const cms = createCMS({
  schema: {
    ...schema,
    MediaFile: Config.mediaFile({
      tabs: {
        analytics: Field.tab('Analytics', {view: '@/views/MediaAnalytics'})
      }
    })
  },
  workspaces
})

import {Config} from 'alinea'
import {createCMS} from 'alinea/next'

// The built-in columns of media folders, without dimensions
const {dimensions, ...columns} = Config.mediaOverview().columns!

export const cms = createCMS({
  schema: {
    ...schema,
    MediaLibrary: Config.mediaLibrary({
      overview: {
        ...Config.mediaOverview(),
        columns: {
          ...columns,
          downloads: Config.column({
            header: 'Downloads',
            view: '@/views/DownloadsCell'
          })
        }
      }
    })
  },
  workspaces
})
